<script setup lang="ts">
// SPDX-License-Identifier: AGPL-3.0-only
import {ref,watch,onMounted,onBeforeUnmount} from 'vue'
import {useLocale} from '../state/locale'
import {useWorkspace} from '../state/workspace'
const store=useWorkspace(),{t,formatDate}=useLocale(),result=ref<any>(null),busy=ref(false),error=ref(''),connecting=ref(false),username=ref(''),appToken=ref('');let alive=true,generation=0
async function load(){if(busy.value)return;const version=++generation;busy.value=true;error.value='';try{if(!store.connection.value)await store.connect();const value=await store.request('reliability');if(alive&&version===generation){result.value=value;if(!username.value)username.value=store.connection.value?.account??''}}catch{if(alive&&version===generation)error.value='Background status is unavailable. Check the companion connection.'}finally{if(alive&&version===generation)busy.value=false}}
watch(()=>store.connection.value?.account,(account,previous)=>{if(account===previous&&account!==undefined||busy.value&&previous===undefined)return;result.value=null;generation++;busy.value=false;if(account||previous===undefined)void load()},{immediate:true});let timer:ReturnType<typeof setInterval>|undefined
onMounted(()=>{timer=setInterval(()=>{if(!busy.value&&!connecting.value)void load()},30000)})
onBeforeUnmount(()=>{clearInterval(timer);alive=false;generation++;appToken.value=''})
async function connect(){if(busy.value)return;busy.value=true;error.value='';try{const access=await store.request('background-connect',{username:username.value,appToken:appToken.value});if(alive){result.value={...result.value,backgroundSession:access};connecting.value=false}}catch{if(alive)error.value='Could not connect the app token. Check its account name, expiry and OpenCloud permissions.'}finally{appToken.value='';busy.value=false}}
async function disconnect(){if(busy.value)return;busy.value=true;error.value='';try{const access=await store.request('background-disconnect');if(alive)result.value={...result.value,backgroundSession:access}}catch{error.value='Could not disconnect background access'}finally{busy.value=false}}
function accessTitle(){const access=result.value?.backgroundSession;return!result.value?'Not checked':!access?.configured?(store.connection.value?.mode==='demo'?'Local simulated worker':'Browser session only'):access.state==='connected'?(access.method==='app_token'?'Connected with an OpenCloud app token':'Background access connected'):access.state==='renewing'?'Renewing background access':access.state==='held'?'Background access needs attention':'Connecting background access'}

</script>
<template><section class="panel reliability-panel" :aria-label="t('Background access')"><div class="reliability-heading"><h2>{{ t('Background access') }}</h2></div><p v-if="error" class="error" role="alert">{{ t(error) }}</p><div class="reliability-grid"><div><h3>{{ t(accessTitle()) }}</h3><p v-if="!result?.backgroundSession?.configured&&store.connection.value?.mode!=='demo'">{{ t('Processing runs on the server. Without an app token, it pauses when web sign-in expires or the server restarts.') }}</p><p v-else-if="result?.backgroundSession?.method==='app_token'&&result.backgroundSession.configured">{{ t('Runs without an open browser. Expired or revoked tokens pause processing.') }}</p><template v-if="store.connection.value?.mode==='live'&&result?.backgroundSession?.available"><button v-if="!connecting" class="button" :disabled="busy" @click="connecting=true">{{ t(result.backgroundSession.configured?'Replace app token':'Connect app token') }}</button><button v-if="result.backgroundSession.configured" class="button subtle" :disabled="busy" @click="disconnect">{{ t('Disconnect') }}</button></template><small v-if="result?.backgroundSession?.expiresAt">{{ t('Access expires: {time}',{time:formatDate(result.backgroundSession.expiresAt)}) }}</small></div></div><form v-if="connecting" class="app-token-form" @submit.prevent="connect"><h3>{{ t('Connect background processing') }}</h3><p>{{ t('Create a Document Workflow token in OpenCloud App Tokens, then enter it here. It uses your account access and is stored privately on this server.') }}</p><a href="/account/extension?extension-id=com.github.opencloud-eu.web.runtime.preferences-panels.app-tokens" target="_blank" rel="noopener">{{ t('Open App Tokens') }}</a><label for="background-username">{{ t('Account name or ID') }}</label><input id="background-username" v-model="username" autocomplete="username" required :disabled="busy" /><label for="background-token">{{ t('App token') }}</label><input id="background-token" v-model="appToken" type="password" autocomplete="new-password" required :disabled="busy" /><div class="settings-footer"><button class="button primary" :disabled="busy||!appToken.trim()">{{ t('Connect') }}</button><button type="button" class="button subtle" :disabled="busy" @click="connecting=false;appToken=''">{{ t('Cancel') }}</button></div></form><details><summary>{{ t('Setup') }}</summary><p>{{ t('Background access uses a token created in OpenCloud. Backups contain document workflow records, never your app token. Restored copies start paused.') }}</p></details></section></template>
<style scoped>.app-token-form{max-width:640px;border-top:1px solid var(--line);padding-top:20px;margin-top:24px}.app-token-form p{font-size:13px}.app-token-form label{display:block;margin:18px 0 7px}.app-token-form input{width:100%}.app-token-form a{display:inline-block;margin-top:12px;color:var(--accent-text)}.reliability-grid .button{margin-top:14px}.reliability-heading{display:flex;align-items:center;justify-content:space-between;gap:14px}.reliability-heading h2{margin:0}.reliability-grid{display:grid;grid-template-columns:1fr;gap:28px;margin:18px 0}.reliability-grid h3{font-size:13px;margin:0}.reliability-grid p,.reliability-panel details{font-size:12px}.reliability-grid small{display:block;color:var(--muted);font-size:11px;margin-top:8px}.reliability-panel summary{cursor:pointer;color:var(--accent-text);padding:6px 0}@media(max-width:700px){.reliability-grid{grid-template-columns:1fr;gap:20px}}</style>
